"use strict";(globalThis.webpackChunkgsf_docusaurus_template=globalThis.webpackChunkgsf_docusaurus_template||[]).push([[2550],{5442(e){e.exports=JSON.parse('{"tag":{"label":"monitoring","permalink":"/tags/monitoring","allTagsPath":"/tags","count":3,"items":[{"id":"operations/capacity-management/match-cpu-capacity-to-average-and-peak-utilization","title":"Match CPU capacity to average and peak utilization","description":"Provisioned CPU capacity has to cover peak demand, so the gap between average and peak utilization determines how much hardware sits idle. Matching CPU capacity to both average and peak utilization reduces idle resources while protecting performance at peak load.","permalink":"/operations/capacity-management/match-cpu-capacity-to-average-and-peak-utilization"},{"id":"requirements/match-slo","title":"Match your service level objectives to business needs","description":"If service downtimes are acceptable it\'s better to not strive for highest availability but to design the solution according to real business needs. Lower availability guarantees can help reduce energy consumption by using less infrastructure components.","permalink":"/requirements/match-slo"},{"id":"requirements/shed-lower-priority-traffic","title":"Shed lower priority traffic","description":"When resources are constrained during high-traffic events or when carbon intensity is high, more carbon emissions will be generated from your system. Adding more resources to support increased traffic requirements introduces more embodied carbon and more demand for electricity. Continuing to handle all requests during high carbon intensity will increase overall emissions for your system. Shedding traffic that is lower priority during these scenarios will save on resources and carbon emissions. This approach requires an understanding of your traffic, including which call requests are critical and which can best withstand retry attempts and failures.","permalink":"/requirements/shed-lower-priority-traffic"}],"unlisted":false}}')}}]);